=item * C<ATRIAL_FIBRILLATION> => C<2>

=item * C<INCONCLUSIVE> => C<3>

=item * C<INCONCLUSIVE_HIGH_HEART_RATE> => C<4>

=item * C<INCONCLUSIVE_LOW_HEART_RATE> => C<5>

=item * C<UNREADABLE> => C<6>

=item * C<NOT_ANALYZED> => C<7>

=back

=head2 Google::Devicesandservices::Health::V4::DataModel::Exercise

An exercise that stores information about a physical activity.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->interval() >> / C<< $msg->interval($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataCoordinates::SessionTimeInterval>)

Required. Observed exercise interval

=item * C<< $msg->exercise_type() >> / C<< $msg->exercise_type($value) >>

Type: C<Enum> (L<Google::Devicesandservices::Health::V4::Exercise::ExerciseType>)

Required. The type of activity performed during an exercise.

=item * C<< $msg->splits() >> / C<< $msg->splits($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::Exercise::SplitSummary>)

Optional. The default split is 1 km or 1 mile.
-  if the movement distance is less than the default,
   then there are no splits
-  if the movement distance is greater than or equal to the
default,
   then we have splits

=item * C<< $msg->exercise_events() >> / C<< $msg->exercise_events($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::Exercise::ExerciseEvent>)

Optional. Exercise events that happen during an exercise, such as pause &
restarts.

=item * C<< $msg->split_summaries() >> / C<< $msg->split_summaries($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::Exercise::SplitSummary>)

Optional. Laps or splits recorded within an exercise.
Laps could be split based on distance or other criteria (duration, etc.)
Laps should not be overlapping with each other.

=item * C<< $msg->metrics_summary() >> / C<< $msg->metrics_summary($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::MetricsSummary>)

Required. Summary metrics for this exercise
( )

=item * C<< $msg->exercise_metadata() >> / C<< $msg->exercise_metadata($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::Exercise::ExerciseMetadata>)

Optional. Additional exercise metadata.

=item * C<< $msg->display_name() >> / C<< $msg->display_name($value) >>

Type: C<String>

Required. The localized, human-readable name of the exercise.
For all exercise types other than `OTHER`, the system ignores client
input and overrides this field with a generated name based on
`exercise_type` (e.g., "Walking" for `WALKING`). If `exercise_type` is
`OTHER`, this field can contain the user's custom, free-form display
name.

=item * C<< $msg->active_duration() >> / C<< $msg->active_duration($value) >>

Type: C<Message> (L<Google::Protobuf::Duration::Duration>)

Optional. Duration excluding pauses.

=item * C<< $msg->notes() >> / C<< $msg->notes($value) >>

Type: C<String>

Optional. Standard free-form notes captured at manual logging.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. This is the timestamp of the last update to the exercise.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Represents the timestamp of the creation of the exercise.

=back

