heartbeats. This is a measure of heart rate variability used by Google
Health. Must be in the range `[1, 200]`.

=item * C<< $msg->standard_deviation_milliseconds() >> / C<< $msg->standard_deviation_milliseconds($value) >>

Type: C<Double>

Optional. The standard deviation of the heart rate variability measurement.

=item * C<< $msg->metadata() >> / C<< $msg->metadata($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::HeartRateVariability::HeartRateVariabilityMetadata>)

Optional. Additional information about the heart rate variability
measurement.

=back

