=head2 Google::Devicesandservices::Health::V4::DataModel::IrregularRhythmNotification

Represents an Irregular Rhythm Notification alert, indicating a potential
sign of atrial fibrillation (AFib).
This data type is based on SaMD feature and any changes to it may require
additional review.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->interval() >> / C<< $msg->interval($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataCoordinates::SessionTimeInterval>)

Required. Observed interval.

=item * C<< $msg->alert_windows() >> / C<< $msg->alert_windows($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::IrregularRhythmNotification::AlertWindow>)

Optional. The overlapping analysis windows that were used to evaluate
rhythm for potential AFib, containing specific information about the user's
heart rhythm.

=item * C<< $msg->medical_device_info() >> / C<< $msg->medical_device_info($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::MedicalDeviceInfo::MedicalDeviceInfo>)

Output only. The meta information for the compatible device used to conduct
the measurement.

Irregular Rhythm Notification measurements typically populate
`algorithm_version`, `service_version`, and `device_model`.

=back

