=head2 Google::Devicesandservices::Health::V4::DataModel::NutritionLog

Holds information about food logged by a user.

There are two ways of creating a nutrition log based on the food type:
1. Identified food: Using the food field, which is a reference to a Food
resource. In this case fields `nutrients`, `energy`, `energy_from_fat`,
`total_carbohydrate`, `total_fat`, `food_display_name` will be populated
based on the referenced food.
2. Anonymous food: Using the `food_display_name` field and setting
the  `nutrients`, `energy`, `energy_from_fat`, `total_carbohydrate`,
`total_fat` fields manually.

The identified food is preferred over the anonymous food.
Nutrition logs created from anonymous food are not editable.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->interval() >> / C<< $msg->interval($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataCoordinates::SessionTimeInterval>)

Required. The time window when the food was logged.

=item * C<< $msg->nutrients() >> / C<< $msg->nutrients($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::NutrientQuantity>)

Optional. An array of individual nutrient values for the nutrition log.

=item * C<< $msg->energy() >> / C<< $msg->energy($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::EnergyQuantity>)

Optional. The total energy of the food, measured in kilocalories (`kcal`).

=item * C<< $msg->energy_from_fat() >> / C<< $msg->energy_from_fat($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::EnergyQuantity>)

Optional. The energy from fat, measured in kilocalories (`kcal`).

=item * C<< $msg->total_carbohydrate() >> / C<< $msg->total_carbohydrate($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::WeightQuantity>)

Optional. The total carbohydrate content, measured in grams.

=item * C<< $msg->total_fat() >> / C<< $msg->total_fat($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::WeightQuantity>)

Optional. The total fat content, measured in grams.

=item * C<< $msg->meal_type() >> / C<< $msg->meal_type($value) >>

Type: C<Enum> (L<Google::Devicesandservices::Health::V4::MealType>)

Optional. The meal category. One of `BREAKFAST`, `LUNCH`, `DINNER`, or
`SNACK`.

=item * C<< $msg->serving() >> / C<< $msg->serving($value) >>

Type: C<Message> (L<Google::Devicesandservices::Health::V4::DataModel::NutritionLog::Serving>)

Optional. The serving information for the logged food.

=item * C<< $msg->food() >> / C<< $msg->food($value) >>

Type: C<String>

Optional. The resource name of the Food item. Required when creating a
nutrition log from an identified food. For anonymous food logs, use the
`food_display_name` field instead.

=item * C<< $msg->food_display_name() >> / C<< $msg->food_display_name($value) >>

Type: C<String>

The display name of the food. For identified food logs, this is populated
automatically from the referenced food.

=back

